head.script:
// https://inswave01.atlassian.net/browse/WAEA-872



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getHeaderValue]<br/>Header Column 정보를 사용하여 특정 Header Column 의 화면 표시값을 반환합니다.",
    "validation" : [
        "headerId(필수) 파라미터로 값을 조회할 Header Column 의 인덱스를 설정할 수 있어야 합니다. (인덱스는 0 부터 시작하며 숨겨진 Column 도 포함하여 설정됩니다.)",
        "특정 Header Column 의 화면 표시값을 반환해야 합니다.",
        "inputType='checkbox' 인 Header Column 은 true/false 값을 반환해야 합니다.",
        "파라미터가 유효하지 않은 경우 undefined 값을 반환해야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 헤더 구성 안내 라벨 생성
    $c.gcm.createLabel('label="인덱스 0: column1(text, header1) / 인덱스 1: column2(text, header2, 숨김) / 인덱스 2: column3(text, header3) / 인덱스 3: chkHeader(checkbox)"', '', 'label1');

    // dataList 생성
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성 (text 헤더 3개 + 숨김 헤더 1개 + checkbox 헤더 1개)
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" checkAllType="include" id="" style="width:520px;height:250px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column1" value="header1"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column2" value="header2" hidden="true"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column3" value="header3"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="checkbox" id="chkHeader" value="chkHeader"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col2" hidden="true" value=""></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="checkbox" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // chkHeader 체크박스 헤더를 선택 상태로 변경 (체크박스 컬럼은 col4 에 바인딩)
    scwin.target1.checkAll('col4', true);
}



scwin.btn_getHeaderValue_onclick = function () {
    // headerId 는 인덱스(Number) 로 전달
    let headerId = Number(par_headerId.getValue());

    let rtn = target1.getHeaderValue(headerId);

    if (typeof rtn === 'undefined') {
        rtn = 'undefined';
    }

    wf_body_bottom.getObj("scwin").setReturnValue("getHeaderValue(" + headerId + ") : " + rtn);
}
